// Ring is an in-memory ring-buffer slog handler keeping the most
// recent capacity records.
type Ring struct {
	mu       sync.RWMutex
	capacity int
	buf      []slog.Record
	start    int // index of oldest record in the logical ordering
	count    int // number of records currently in buffer
	attrs    []slog.Attr
	groups   []string
}

// NewRing creates a new Ring handler with the given capacity.
func NewRing(capacity int) (*Ring, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("logfan.NewRing: capacity must be positive, got %d", capacity)
	}
	return &Ring{
		capacity: capacity,
		buf:      make([]slog.Record, capacity),
	}, nil
}

// Enabled implements slog.Handler.
func (r *Ring) Enabled(_ context.Context, level slog.Level) bool {
	return true
}

// Handle implements slog.Handler.
func (r *Ring) Handle(_ context.Context, record slog.Record) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	// Clone the record and its attrs
	rec := record.Clone()
	// Add any pre-existing attrs from WithAttrs
	rec.AddAttrs(r.attrs...)

	idx := (r.start + r.count) % r.capacity
	if r.count == r.capacity {
		// buffer is full, overwrite oldest
		r.buf[idx] = rec
		r.start = (r.start + 1) % r.capacity
	} else {
		r.buf[idx] = rec
		r.count++
	}

	return nil
}

// WithAttrs implements slog.Handler.
func (r *Ring) WithAttrs(attrs []slog.Attr) slog.Handler {
	r.mu.RLock()
	defer r.mu.RUnlock()

	newAttrs := make([]slog.Attr, len(r.attrs)+len(attrs))
	copy(newAttrs, r.attrs)
	copy(newAttrs[len(r.attrs):], attrs)

	return &Ring{
		capacity: r.capacity,
		buf:      make([]slog.Record, r.capacity),
		attrs:    newAttrs,
		groups:   append([]string{}, r.groups...),
	}
}

// WithGroup implements slog.Handler.
func (r *Ring) WithGroup(name string) slog.Handler {
	r.mu.RLock()
	defer r.mu.RUnlock()

	return &Ring{
		capacity: r.capacity,
		buf:      make([]slog.Record, r.capacity),
		attrs:    append([]slog.Attr{}, r.attrs...),
		groups:   append(append([]string{}, r.groups...), name),
	}
}

// Records returns the buffered records, oldest first.
func (r *Ring) Records() []slog.Record {
