package logfan

import (
	"context"
	"fmt"
	"log/slog"
	"sync"
)

// Ring is an in-memory ring-buffer slog handler keeping the most recent
// capacity records.
type Ring struct {
	mu       sync.RWMutex
	capacity int
	buf      []slog.Record // physical array; logical order maintained by start/count
	start    int           // index of oldest record
	count    int           // number of records currently stored
}

// NewRing creates a Ring handler that retains at most capacity records.
func NewRing(capacity int) (*Ring, error) {
	if capacity <= 0 {
		return nil, fmt.Errorf("logfan.NewRing: capacity must be positive, got %d", capacity)
	}
	return &Ring{
		capacity: capacity,
		buf:      make([]slog.Record, capacity),
	}, nil
}

// Enabled implements slog.Handler. Always returns true.
func (r *Ring) Enabled(_ context.Context, _ slog.Level) bool { return true }

// Handle implements slog.Handler.
func (r *Ring) Handle(_ context.Context, record slog.Record) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	idx := (r.start + r.count) % r.capacity
	rec := record.Clone()
	r.buf[idx] = rec
	if r.count < r.capacity {
		r.count++
	} else {
		r.start = (r.start + 1) % r.capacity
	}
	return nil
}

// WithAttrs implements slog.Handler.
func (r *Ring) WithAttrs(attrs []slog.Attr) slog.Handler {
	r2 := &Ring{capacity: r.capacity, buf: make([]slog.Record, r.capacity)}
	_ = attrs // attrs are added to the record by slog.Logger before Handle
	return r2
}

// WithGroup implements slog.Handler.
func (r *Ring) WithGroup(name string) slog.Handler {
	r2 := &Ring{capacity: r.capacity, buf: make([]slog.Record, r.capacity)}
	_ = name
	return r2
}

// Records returns the buffered records, oldest first. The returned slice is a
// deep copy; mutating it does not affect the Ring.
func (r *Ring) Records() []slog.Record {
	r.mu.RLock()
	defer r.mu.RUnlock()

	if r.count == 0 {
		return nil
	}
	out := make([]slog.Record, r.count)
	for i := 0; i < r.count; i++ {
		idx := (r.start + i) % r.capacity
		out[i] = r.buf[idx].Clone()
	}
	return out
}

// multiHandler fans every record out to all registered handlers.
type multiHandler struct {
	handlers []slog.Handler
}

// New builds a logger that delivers every record to ALL given handlers.
func New(handlers ...slog.Handler) (*slog.Logger, error) {
	if len(handlers) == 0 {
		return nil, fmt.Errorf("logfan.New: at least one handler is required")
	}
	return slog.New(&multiHandler{handlers: handlers}), nil
}

func (m *multiHandler) Enabled(ctx context.Context, level slog.Level) bool {
	for _, h := range m.handlers {
		if h.Enabled(ctx, level) {
			return true
		}
	}
	return false
}

func (m *multiHandler) Handle(ctx context.Context, record slog.Record) error {
	for _, h := range m.handlers {
		if err := h.Handle(ctx, record); err != nil {
			return err
		}
	}
	return nil
}

func (m *multiHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	hs := make([]slog.Handler, len(m.handlers))
	for i, h := range m.handlers {
		hs[i] = h.WithAttrs(attrs)
	}
	return &multiHandler{handlers: hs}
}

func (m *multiHandler) WithGroup(name string) slog.Handler {
	hs := make([]slog.Handler, len(m.handlers))
	for i, h := range m.handlers {
		hs[i] = h.WithGroup(name)
	}
	return &multiHandler{handlers: hs}
}

package logfan

import (
	"context"
	"log/slog"
	"sync"
	"testing"
	"time"
)

// ---------------------------------------------------------------------------
// NewRing
// ---------------------------------------------------------------------------

func TestNewRing_InvalidCapacity(t *testing.T) {
	_, err := NewRing(0)
	if err == nil {
		t.Fatal("expected error for capacity 0")
	}
	_, err = NewRing(-1)
	if err == nil {
		t.Fatal("expected error for capacity -1")
	}
}

func TestNewRing_Ok(t *testing.T) {
	r, err := NewRing(5)
	if err != nil {
		t.Fatal(err)
	}
	if r.Records() != nil {
		t.Fatal("new ring should have nil records")
	}
}

// ---------------------------------------------------------------------------
// Ring basic store/retrieve
// ---------------------------------------------------------------------------

func TestRing_StoreSingle(t *testing.T) {
	r, _ := NewRing(3)
	rec := slog.NewRecord(time.Now(), slog.LevelInfo, "hello", 0)
	if err := r.Handle(context.Background(), rec); err != nil {
		t.Fatal(err)
	}
	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("want 1 record, got %d", len(recs))
	}
	if recs[0].Message != "hello" {
		t.Fatalf("want message 'hello', got %q", recs[0].Message)
	}
}

func TestRing_OldestFirst(t *testing.T) {
	r, _ := NewRing(5)
	for _, msg := range []string{"a", "b", "c"} {
		rec := slog.NewRecord(time.Now(), slog.LevelInfo, msg, 0)
		r.Handle(context.Background(), rec)
	}
	recs := r.Records()
	if len(recs) != 3 {
		t.Fatalf("want 3 records, got %d", len(recs))
	}
	for i, want := range []string{"a", "b", "c"} {
		if recs[i].Message != want {
			t.Fatalf("record %d: want %q, got %q", i, want, recs[i].Message)
		}
	}
}

func TestRing_EvictsOldest(t *testing.T) {
	r, _ := NewRing(3)
	for _, msg := range []string{"a", "b", "c", "d", "e"} {
		rec := slog.NewRecord(time.Now(), slog.LevelInfo, msg, 0)
		r.Handle(context.Background(), rec)
	}
	recs := r.Records()
	if len(recs) != 3 {
		t.Fatalf("want 3 records, got %d", len(recs))
	}
	// "c", "d", "e" should remain; "a", "b" evicted
	for i, want := range []string{"c", "d", "e"} {
		if recs[i].Message != want {
			t.Fatalf("record %d: want %q, got %q", i, want, recs[i].Message)
		}
	}
}

func TestRing_EvictWraparound(t *testing.T) {
	// capacity 2, write 7 + 1 = 8 records to force multiple wraparounds
	r, _ := NewRing(2)
	for i := 0; i < 8; i++ {
		rec := slog.NewRecord(time.Now(), slog.LevelInfo, "x", 0)
		r.Handle(context.Background(), rec)
	}
	recs := r.Records()
	if len(recs) != 2 {
		t.Fatalf("want 2 records, got %d", len(recs))
	}
}

// ---------------------------------------------------------------------------
// Records deep-copy
// ---------------------------------------------------------------------------

func TestRing_RecordsCopy(t *testing.T) {
	r, _ := NewRing(3)
	rec := slog.NewRecord(time.Now(), slog.LevelInfo, "msg", 0)
	rec.AddAttrs(slog.String("k", "original"))
	r.Handle(context.Background(), rec)

	recs := r.Records()
	// mutate the returned record
	recs[0] = slog.NewRecord(time.Now(), slog.LevelInfo, "tampered", 0)

	// ring should still hold the original
	recs2 := r.Records()
	if recs2[0].Message != "msg" {
		t.Fatalf("ring was mutated: got %q, want %q", recs2[0].Message, "msg")
	}
}

// ---------------------------------------------------------------------------
// Concurrent safety
// ---------------------------------------------------------------------------

func TestRing_ConcurrentSafe(t *testing.T) {
	r, _ := NewRing(100)
	var wg sync.WaitGroup

	// 20 concurrent writers
	for i := 0; i < 20; i++ {
		wg.Add(1)
		go func(n int) {
			defer wg.Done()
			for j := 0; j < 50; j++ {
				rec := slog.NewRecord(time.Now(), slog.LevelInfo, "test", 0)
				r.Handle(context.Background(), rec)
			}
		}(i)
	}

	// 10 concurrent readers
	for i := 0; i < 10; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < 20; j++ {
				r.Records()
			}
		}()
	}

	wg.Wait()

	recs := r.Records()
	if len(recs) != 100 {
		t.Fatalf("want 100 records, got %d", len(recs))
	}
}

// ---------------------------------------------------------------------------
// Enabled
// ---------------------------------------------------------------------------

func TestRing_Enabled(t *testing.T) {
	r, _ := NewRing(3)
	if !r.Enabled(context.Background(), slog.LevelDebug) {
		t.Fatal("Enabled should return true for Debug")
	}
	if !r.Enabled(context.Background(), slog.LevelError) {
		t.Fatal("Enabled should return true for Error")
	}
}

// ---------------------------------------------------------------------------
// WithAttrs / WithGroup
// ---------------------------------------------------------------------------

func TestRing_WithAttrs(t *testing.T) {
	r, _ := NewRing(3)
	h := r.WithAttrs([]slog.Attr{slog.String("tag", "a")})
	rec := slog.NewRecord(time.Now(), slog.LevelInfo, "with-attrs", 0)
	if err := h.Handle(context.Background(), rec); err != nil {
		t.Fatal(err)
	}
	// Ring handler doesn't persist attrs across instances,
	// but the returned handler is a working Ring.
	rr := h.(*Ring)
	recs := rr.Records()
	if len(recs) != 1 || recs[0].Message != "with-attrs" {
		t.Fatal("WithAttrs handler lost record")
	}
}

func TestRing_WithGroup(t *testing.T) {
	r, _ := NewRing(3)
	h := r.WithGroup("g")
	rec := slog.NewRecord(time.Now(), slog.LevelInfo, "with-group", 0)
	if err := h.Handle(context.Background(), rec); err != nil {
		t.Fatal(err)
	}
	rr := h.(*Ring)
	recs := rr.Records()
	if len(recs) != 1 || recs[0].Message != "with-group" {
		t.Fatal("WithGroup handler lost record")
	}
}

// ---------------------------------------------------------------------------
// slog.Logger integration
// ---------------------------------------------------------------------------

func TestRing_LoggerIntegration(t *testing.T) {
	r, _ := NewRing(5)
	logger := slog.New(r)
	logger.Info("integration test")

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("want 1 record, got %d", len(recs))
	}
	if recs[0].Message != "integration test" {
		t.Fatalf("want message 'integration test', got %q", recs[0].Message)
	}
	if recs[0].Level != slog.LevelInfo {
		t.Fatalf("want level Info, got %v", recs[0].Level)
	}
}

func TestRing_LoggerWithAttrs(t *testing.T) {
	r, _ := NewRing(5)
	logger := slog.New(r).With("key", "value")
	logger.Info("with attrs")

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatal("expected 1 record")
	}
	// slog.Logger adds attrs to the record before Handle
	var found bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "key" && a.Value.String() == "value" {
			found = true
			return false
		}
		return true
	})
	if !found {
		t.Fatal("expected attr 'key=value' in record")
	}
}

// ---------------------------------------------------------------------------
// New (fan-out)
// ---------------------------------------------------------------------------

func TestNew_NoHandlers(t *testing.T) {
	_, err := New()
	if err == nil {
		t.Fatal("expected error for zero handlers")
	}
}

func TestNew_FanOut(t *testing.T) {
	r1, _ := NewRing(5)
	r2, _ := NewRing(5)

	logger, err := New(r1, r2)
	if err != nil {
		t.Fatal(err)
	}

	logger.Info("fan-out test")

	recs1 := r1.Records()
	recs2 := r2.Records()

	if len(recs1) != 1 || recs1[0].Message != "fan-out test" {
		t.Fatal("r1 didn't receive the record")
	}
	if len(recs2) != 1 || recs2[0].Message != "fan-out test" {
		t.Fatal("r2 didn't receive the record")
	}
}

func TestNew_FanOutWithHandlerAttrs(t *testing.T) {
	r1, _ := NewRing(5)
	r2, _ := NewRing(5)

	logger, err := New(r1, r2)
	if err != nil {
		t.Fatal(err)
	}

	logger.With("shared", "val").Info("fan-out with attrs")

	recs1 := r1.Records()
	recs2 := r2.Records()

	if len(recs1) != 1 || len(recs2) != 1 {
		t.Fatal("both handlers should have received the record")
	}

	for _, recs := range [][]slog.Record{recs1, recs2} {
		var found bool
		recs[0].Attrs(func(a slog.Attr) bool {
			if a.Key == "shared" && a.Value.String() == "val" {
				found = true
				return false
			}
			return true
		})
		if !found {
			t.Fatal("expected attr 'shared=val' in record")
		}
	}
}

func TestMultiHandler_Enabled(t *testing.T) {
	r1, _ := NewRing(1)
	r2, _ := NewRing(1)
	mh := &multiHandler{handlers: []slog.Handler{r1, r2}}

	if !mh.Enabled(context.Background(), slog.LevelDebug) {
		t.Fatal("multiHandler.Enabled should be true")
	}
}

