	r.mu.RLock()
	defer r.mu.RUnlock()

	merged := make([]slog.Attr, len(r.preAttrs)+len(attrs))
	copy(merged, r.preAttrs)
	copy(merged[len(r.preAttrs):], attrs)
	return &Ring{capacity: r.capacity, buf: make([]slog.Record, r.capacity), preAttrs: merged}
}

